DROP TABLE IF EXISTS `file_meta`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `file_meta` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uuid` varchar(64) NOT NULL COMMENT '对外唯一标识',
  `oss_path` varchar(500) NOT NULL COMMENT 'OSS真实路径',
  `file_type` varchar(20) NOT NULL COMMENT '文件类型：avatar/cover/content',
  `target_id` bigint(20) NOT NULL COMMENT '业务主键ID（avatar/user_id、cover/article_id、carousel/carousel_id、content/article_id 无业务关联填0）',
  `is_original` tinyint(1) DEFAULT '1' COMMENT '是否原始上传 1=是 0=否',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '软删除标记 0=有效 1=已删',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_target_type` (`target_id`,`file_type`) USING BTREE,
  KEY `idx_deleted_created` (`is_deleted`,`create_time`) USING BTREE,
  KEY `idx_uuid` (`uuid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='文件映射元数据表';
