  `ipaddr` varchar(50) DEFAULT NULL COMMENT 'ip地址',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_username_status` (`username`,`status`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
