--
-- Table structure for table `notice`
--

DROP TABLE IF EXISTS `notice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `notice` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) DEFAULT NULL,
  `content` longtext NOT NULL COMMENT '公告内容',
  `type` tinyint(1) DEFAULT '0' COMMENT '消息类型： 0为普通消息，1为 md长文本 消息',
  `target_type` tinyint(4) DEFAULT '1' COMMENT '推送范围：1-前台用户 2-后台管理员 3-全部（前台+后台',
  `status` tinyint(4) DEFAULT '0' COMMENT '状态：0-草稿 1-已推送 2-已下架',
  `push_scope` tinyint(4) DEFAULT '1' COMMENT '1-全部后台用户 2-指定用户',
  `push_time` datetime DEFAULT NULL COMMENT '推送时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除 0代表未删除，1代表已删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_status_push_time` (`status`,`push_time`) USING BTREE,
  KEY `idx_target_status` (`target_type`,`status`) USING BTREE,
  KEY `idx_is_deleted` (`is_deleted`) USING BTREE,
  KEY `idx_target_type` (`target_type`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='公告表';
/*!40101 SET character_set_client = @saved_cs_client */;

