--
-- Table structure for table `sys_task`
--

DROP TABLE IF EXISTS `sys_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_task` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `task_code` varchar(50) NOT NULL COMMENT '任务编码（唯一标识，如：VIEW_COUNT_SYNC）',
  `task_name` varchar(100) NOT NULL COMMENT '任务名称（中文，如：浏览量同步任务）',
  `description` varchar(255) DEFAULT NULL COMMENT '任务描述（详细说明）',
  `cron_expression` varchar(50) NOT NULL COMMENT 'cron表达式',
  `status` tinyint(4) DEFAULT '1' COMMENT '状态：0启用 1禁用',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_task_code` (`task_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='定时任务配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_task`
--

LOCK TABLES `sys_task` WRITE;
/*!40000 ALTER TABLE `sys_task` DISABLE KEYS */;
INSERT INTO `sys_task` VALUES (1,'VIEW_COUNT_SYNC','浏览量同步任务','将Redis中的浏览量数据同步到MySQL数据库','0 0/15 * * * ?',0,'2023-06-05 10:23:41','2023-06-08 14:12:27'),(3,'COMMENT_COUNT_SYNC','评论数同步任务','定时同步评论表数据，更新文章表的评论总数','0 0/30 * * * ?',1,'2023-06-12 15:47:52','2023-06-15 11:35:18'),(4,'LOGICAL_DELETE_FILE_META_CLEANUP','逻辑删除文件元数据清理任务','清理30天前逻辑删除（is_deleted=1）的业务数据关联的file_meta记录（文章封面/内容图、用户头像、轮播图）','0 0 1 */7 * ?',0,'2023-06-19 09:09:33','2023-06-22 16:58:44'),(5,'PHYSICAL_DELETE_FILE_META_CLEANUP','物理删除文件元数据清理任务','扫描file_meta表，检查对应业务数据（文章/用户/轮播）是否已被MySQL物理删除，若不存在则软删除file_meta记录','0 0 2 */10 * ?',0,'2023-06-26 14:31:15','2023-06-29 10:17:29'),(6,'FILE_PHYSICAL_DELETE','OSS文件物理删除任务','清理7天前软删除（is_deleted=1）的file_meta记录，从OSS删除物理文件并删除数据库记录','0 0 3 */5 * ?',0,'2023-07-04 11:54:28','2023-07-07 15:43:56'),(7,'REDIS_CACHE_SYNC','Redis缓存同步任务','同步file_meta表和Redis缓存：正向同步（is_deleted=1删除缓存，is_deleted=0重建缓存）+ 反向校验（扫描Redis中images:前缀的Key，若UUID在file_meta中不存在则删除缓存）','0 0 4 */2 * ?',0,'2023-07-11 10:18:07','2023-07-14 14:05:33'),(8,'BUSINESS_TITLE_CACHE_CLEANUP','业务标题缓存清理任务','定期清理 Redis 中已失效的业务标题缓存（文章/用户/轮播标题）','0 0 5 */10 * ?',0,'2023-07-18 16:42:39','2023-07-21 09:31:12'),(9,'LOG_CLEANUP','日志清理任务','定时清理过期的登录日志和操作日志，根据配置保留最近N天的日志','0 0 6 */10 * ?',0,'2023-07-25 09:05:51','2023-07-28 15:49:27'),(10,'NOTICE_READ_CLEANUP','已读公告清理任务','清理超过60天的notice_read已读记录','0 0 3 * * ?',0,'2023-08-02 11:29:04','2023-08-05 16:18:43'),(11,'NOTICE_OFFLINE_CLEANUP','下架公告清理任务','清理超过60天的下架公告及关联数据（Redis未读、已读记录、指定用户关联）','0 0 4 * * ?',0,'2023-08-09 14:53:46','2023-08-12 10:37:58');
/*!40000 ALTER TABLE `sys_task` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `sys_user`
--

DROP TABLE IF EXISTS `sys_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_user` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '会员id',
  `username` varchar(20) NOT NULL DEFAULT '' COMMENT '用户名',
  `password` varchar(65) NOT NULL DEFAULT '1234' COMMENT '密码',
  `nickname` varchar(50) DEFAULT NULL COMMENT '姓名',
  `email` varchar(64) DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(11) DEFAULT NULL COMMENT '手机',
  `avatar` varchar(200) DEFAULT NULL COMMENT '头像地址',
  `url_id` bigint(20) DEFAULT NULL COMMENT '对外URL数字ID(15位随机,不可枚举)',
  `description` varchar(255) DEFAULT NULL COMMENT '描述',
  `bio` varchar(500) DEFAULT NULL COMMENT '个人简介',
  `type` tinyint(1) DEFAULT '0' COMMENT '用户类型：0代表后台用户，1代表前台用户',
  `status` tinyint(3) DEFAULT '0' COMMENT '状态（0：正常 1：停用）',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `is_deleted` tinyint(3) NOT NULL DEFAULT '0' COMMENT '删除标记（0:可用 1:已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `idx_username` (`username`) USING BTREE,
  UNIQUE KEY `uk_sys_user_url_id` (`url_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

